/**
 * Trial banner container — the intended `bannerTop` binding for the
 * app-shell's `ShellConfig` seam (`@/lib/shell-config`).
 *
 * `shellConfig.bannerTop` is rendered with no props (inside
 * `SidebarInset`, above `main`), so this wrapper resolves the active
 * workspace, fetches its trial status, and decides whether the client
 * `TrialBanner` renders at all. An async Server Component is a valid
 * `bannerTop` binding — React 19's `FunctionComponent` allows
 * `Promise<ReactNode>` — so the fetch happens server-side rather than
 * through a client round trip.
 *
 * A trial that isn't active (none, converted, depleted, expired)
 * renders nothing; so does a fetch failure — a broken banner lookup
 * must never take the shell down with it.
 *
 * Route suppression (e.g. keeping the banner out of the chat surface)
 * is client-side in `TrialBanner` via `trialBannerConfig.hideOnPaths` —
 * a Server Component outside the `[locale]` segment has no reliable
 * pathname to branch on.
 */

import { getWorkspaceContext } from "@intelligo-dev/auth";
import { getTrialStatus } from "@intelligo-dev/billing";
import { createLogger } from "@intelligo-dev/core/logger";

import { TrialBanner } from "./trial-banner";

const log = createLogger("TrialBannerContainer");

export async function TrialBannerContainer() {
  const workspace = await getWorkspaceContext();
  if (!workspace?.workspace?.id) return null;

  try {
    const trial = await getTrialStatus(workspace.workspace.id);
    if (
      trial.status !== "active" ||
      trial.isExpired ||
      trial.daysRemaining <= 0
    ) {
      return null;
    }

    return (
      <TrialBanner
        daysRemaining={trial.daysRemaining}
        creditsRemaining={trial.creditsRemaining}
        initialCredits={trial.initialCredits}
      />
    );
  } catch (error) {
    log.error("Failed to fetch trial status", {
      error: error instanceof Error ? error.message : String(error),
    });
    return null;
  }
}

"use client";

/**
 * Trial banner — a dismissable strip above the app shell's content
 * showing days and credits remaining, with an upgrade CTA.
 *
 * Urgency ramps the visual weight with plain shadcn tokens (no product
 * palette): normal (>3 days) sits on `primary`, warning (≤3 days) on
 * `foreground`/`muted`, urgent (≤1 day) on `destructive`. Dismissing
 * hides the banner for the rest of the day (localStorage; per-browser,
 * deliberately not server state — a nudge, not a notification).
 *
 * `trialBannerConfig` (consumer-owned `lib/trial-banner-config.ts`)
 * decides where the upgrade CTA points and which route prefixes
 * suppress the banner entirely — the default keeps it out of `/chat`,
 * where a persistent strip over a conversation costs the most.
 */

import { useEffect, useState } from "react";
import { Sparkles, X } from "lucide-react";
import { useFormatter, useTranslations } from "next-intl";

import { Link, usePathname } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import { trialBannerConfig } from "@/lib/trial-banner-config";

const DISMISSED_KEY = "trial-banner-dismissed";

/** Local calendar day, as a stable `YYYY-MM-DD` storage key. */
function today(): string {
  return new Date().toISOString().slice(0, 10);
}

type TrialBannerProps = {
  daysRemaining: number;
  creditsRemaining: number;
  initialCredits: number;
};

export function TrialBanner({
  daysRemaining,
  creditsRemaining,
  initialCredits,
}: TrialBannerProps) {
  const t = useTranslations("trial-banner");
  const format = useFormatter();
  const pathname = usePathname();
  const [isVisible, setIsVisible] = useState(true);

  // Dismissed-today check runs in an effect: localStorage doesn't exist
  // during SSR, and reading it during render would desync hydration.
  useEffect(() => {
    if (localStorage.getItem(DISMISSED_KEY) === today()) {
      setIsVisible(false);
    }
  }, []);

  const hidden = trialBannerConfig.hideOnPaths.some(
    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`)
  );
  if (hidden || !isVisible) return null;

  function handleDismiss() {
    localStorage.setItem(DISMISSED_KEY, today());
    setIsVisible(false);
  }

  const isUrgent = daysRemaining <= 1;
  const isWarning = daysRemaining > 1 && daysRemaining <= 3;

  const strip = isUrgent
    ? "bg-destructive/10 border-destructive/20"
    : isWarning
      ? "bg-muted border-border"
      : "bg-primary/5 border-primary/20";
  const accent = isUrgent
    ? "text-destructive"
    : isWarning
      ? "text-foreground"
      : "text-primary";
  const chip = isUrgent
    ? "bg-destructive/10 text-destructive"
    : isWarning
      ? "bg-foreground/10 text-foreground"
      : "bg-primary/10 text-primary";

  const compact = (value: number) =>
    format.number(value, { notation: "compact", maximumFractionDigits: 1 });

  return (
    <div className={`relative w-full border-b transition-colors ${strip}`}>
      <div className="container mx-auto px-4 py-3">
        <div className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <Sparkles className={`h-5 w-5 ${accent}`} aria-hidden />
            <div className="flex flex-col sm:flex-row sm:items-center sm:gap-2">
              <div className="flex items-center gap-2">
                <span
                  className={`inline-flex items-center rounded-md px-2 py-1 text-xs font-medium ${chip}`}
                >
                  {t("label")}
                </span>
                <span className={`text-sm font-semibold ${accent}`}>
                  {daysRemaining === 0
                    ? t("expiresToday")
                    : t("daysRemaining", { days: daysRemaining })}
                </span>
              </div>
              <span className={`text-xs ${accent}`}>
                {t("creditsLeft", {
                  remaining: compact(creditsRemaining),
                  initial: compact(initialCredits),
                })}
              </span>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Button
              size="sm"
              variant={isUrgent ? "destructive" : "default"}
              render={<Link href={trialBannerConfig.upgradeHref} />}
              nativeButton={false}
            >
              {t("upgrade")}
            </Button>
            <button
              type="button"
              onClick={handleDismiss}
              className="rounded-md p-1 text-muted-foreground transition-colors hover:bg-muted"
              aria-label={t("dismiss")}
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Trial banner config — consumer-owned.
 *
 * `hideOnPaths`: locale-less route prefixes where the banner never
 * renders (matched against `@/i18n/navigation`'s `usePathname`, exact
 * or as a path-segment prefix). The default keeps it off the chat
 * surface — a persistent strip over a conversation is where a banner
 * costs the most. Empty the list to show it everywhere.
 *
 * `upgradeHref`: where the CTA sends the user.
 */

export interface TrialBannerConfig {
  hideOnPaths: string[];
  upgradeHref: string;
}

export const trialBannerConfig: TrialBannerConfig = {
  hideOnPaths: ["/chat"],
  upgradeHref: "/pricing",
};
